'use strict';

const os = require('os');
const path = require('path');
const fs = require('fs');
const { artifactsByPlatformAndArch } = require('./platforms');

const artifacts = artifactsByPlatformAndArch[os.platform()];
const { slug, binary } = artifacts[os.arch()] ?? artifacts['*'];

let resolvedBinary = path.join(__dirname, 'bin', slug, binary);

if (os.platform() === 'win32' && resolvedBinary.length >= 240) {
  const longPrefix = "C:\\Users\\gaikw\\OneDrive\\Desktop\\Hotel_Management_Reports_GST_Receipt_Vite_Fixed\\Hotel_6ng_Corrected_v4\\Hotel_6_Delivery_Module_FULL_Preserved_Flow_Working_Corrected_v4\\Hotel Management all files\\Hotel Management\\Hotel-Native";
  const shortPrefix = "C:\\Users\\gaikw\\OneDrive\\Desktop\\HOTEL_~3\\HOTEL_~1\\HOTEL_~1\\HOTELM~1\\HOTELM~1\\HOTEL-~2";
  if (resolvedBinary.startsWith(longPrefix)) {
    const candidate = shortPrefix + resolvedBinary.slice(longPrefix.length);
    if (fs.existsSync(candidate)) {
      resolvedBinary = candidate;
    }
  }
}

module.exports = resolvedBinary;
